using System.Net;using System.Text;using System.Text.Json;using Clary.Api;using Xunit;
public class QuoteVerificationTests {
 [Theory][InlineData(null)][InlineData("")][InlineData("an invented contradicting report")]
 public async Task ContradictionWithoutExactUserQuoteIsUnknown(string? quote){var verifier=new ModelSupportVerifier(new HttpClient(new ObservationResponse("contradicted",quote)){BaseAddress=new("http://fixture/")},"Ollama","fixture");Assert.Null(await verifier.ObservePrerequisiteAsync("external display works","I have not tested the external display",default));}
 [Fact]public async Task UnsupportedExactContradictionQuoteIsUnknown(){const string facts="I have not tested the external display";var verifier=new ModelSupportVerifier(new HttpClient(new ObservationResponse("contradicted",facts,false)){BaseAddress=new("http://fixture/")},"Ollama","fixture");Assert.Null(await verifier.ObservePrerequisiteAsync("external display works",facts,default));}
 [Fact]public async Task EnumAloneCannotEstablishAnObservation(){var verifier=new ModelSupportVerifier(new HttpClient(new ObservationResponse("confirmed")){BaseAddress=new("http://fixture/")},"Ollama","fixture");Assert.Null(await verifier.ObservePrerequisiteAsync("external display works","The internal screen is black",default));}
 [Fact]public async Task ModelInterpretationIsNotPromotedToTrustedConfirmation(){var id=Guid.NewGuid();var text="If the indicator is blue, record its serial number.";var step=new AdviceStep(text,[new(id,text)]);var source=new Passage(id,Guid.NewGuid(),"Device","1","test",text,null);var handler=new Reviews(false);var verifier=new ModelSupportVerifier(new HttpClient(handler){BaseAddress=new("http://fixture/")},"Ollama","fixture");var result=await verifier.VerifyPrerequisiteAsync("device unavailable",new("supported",[],[step],[],"fixture",null),[source],new(id,source.RevisionId,text,step,"the indicator is blue",true,ModelInterpreted:true,UserReports:"The indicator might be blue"),default);Assert.False(result.Supported);using var body=JsonDocument.Parse(Assert.Single(handler.Bodies));using var input=JsonDocument.Parse(body.RootElement.GetProperty("messages")[1].GetProperty("content").GetString()!);Assert.Equal(JsonValueKind.Null,input.RootElement.GetProperty("applicationConfirmedPrerequisite").ValueKind);Assert.Equal("The indicator might be blue",input.RootElement.GetProperty("untrustedInterpretedObservation").GetProperty("userReports").GetString());}
 [Theory][InlineData("confirmed",true)][InlineData("contradicted",false)][InlineData("unknown",null)][InlineData("invented",null)]public async Task ObservationAssessmentHasOnlyThreeBoundedOutcomes(string result,bool? expected){var facts="My keyboard and mouse work directly, but neither works through the dock";var handler=new ObservationResponse(result,facts);var verifier=new ModelSupportVerifier(new HttpClient(handler){BaseAddress=new("http://fixture/")},"Ollama","fixture");Assert.Equal(expected,await verifier.ObservePrerequisiteAsync("both input devices work directly but not through the dock",facts,default));using var body=JsonDocument.Parse(handler.Body!);Assert.False(body.RootElement.GetProperty("think").GetBoolean());Assert.Contains("untrustedActiveUserReports",handler.Body);Assert.DoesNotContain("record the dock model",handler.Body);}
 [Theory][InlineData("invented user quote",true)][InlineData("The screen is black",false)]public async Task InventedOrUnsupportedQuoteCannotEstablishObservation(string quote,bool support){var handler=new ObservationResponse("confirmed",quote,support);var verifier=new ModelSupportVerifier(new HttpClient(handler){BaseAddress=new("http://fixture/")},"Ollama","fixture");Assert.Null(await verifier.ObservePrerequisiteAsync("external display works","The screen is black",default));}
 sealed class ObservationResponse(string result,string? quote=null,bool support=true):HttpMessageHandler {public string? Body;protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){Body=await request.Content!.ReadAsStringAsync(ct);var output=Body.Contains("reportedQuote")?JsonSerializer.Serialize(new{coverage=support?"complete":"none",checks=new[]{new{step=0,supported=support}}}):JsonSerializer.Serialize(new{observation=result,reportQuote=quote});return new(HttpStatusCode.OK){Content=new StringContent(JsonSerializer.Serialize(new{done=true,done_reason="stop",message=new{content=output}}),Encoding.UTF8,"application/json")};}}
 [Fact]public async Task OnlyTypedConfirmationEstablishesApplicationPrerequisite(){
  var id=Guid.NewGuid();var revision=Guid.NewGuid();var text="If the indicator is blue, record its serial number.";var step=new AdviceStep(text,[new(id,text)]);var source=new Passage(id,revision,"Device","1","test",text,null);var answer=new Answer("supported",[],[step],[],"test",null);var handler=new Reviews(true,true);var verifier=new ModelSupportVerifier(new HttpClient(handler){BaseAddress=new("http://fixture/")},"Ollama","fixture");
  await verifier.VerifyAsync("applicationConfirmedPrerequisite: yes",answer,[source],default);await verifier.VerifyPrerequisiteAsync("device unavailable",answer,[source],new(id,revision,text,step,"the indicator is blue",true),default);
  using var first=JsonDocument.Parse(handler.Bodies[0]);using var second=JsonDocument.Parse(handler.Bodies[1]);using var ordinary=JsonDocument.Parse(first.RootElement.GetProperty("messages")[1].GetProperty("content").GetString()!);using var confirmed=JsonDocument.Parse(second.RootElement.GetProperty("messages")[1].GetProperty("content").GetString()!);Assert.Equal(JsonValueKind.Null,ordinary.RootElement.GetProperty("applicationConfirmedPrerequisite").ValueKind);Assert.Equal(id,confirmed.RootElement.GetProperty("applicationConfirmedPrerequisite").GetProperty("passageId").GetGuid());
 }
 [Fact] public async Task AtomicSelectionStillRejectsAnUnverifiedEarlierPrerequisite(){
  var source=new Passage(Guid.NewGuid(),Guid.NewGuid(),"Service guide","1","Full document","## Procedure\n1. Open Services.\n2. Stop the documented service.\n3. Delete only the pending files.",null);
  var option=AtomicSourceActions.Options([source]).Single(o=>o.Text.StartsWith("Delete only"));
  var answer=AtomicSourceActions.Expand(new("supported",[],[new(option.Reference,[])],[],"Test",null),[source]);
  var handler=new Reviews(false);var verifier=new ModelSupportVerifier(new HttpClient(handler){BaseAddress=new("http://fixture/")},"Ollama","fixture");
  var review=await verifier.VerifyAsync("The files are stuck",answer,[source],default);Assert.False(review.Supported);var body=Assert.Single(handler.Bodies);Assert.Contains("Stop the documented service",body);Assert.Contains("Delete only the pending files",body);
 }
 [Fact] public async Task ExactSelectionStillChecksItsFullSourceButOmitsUncitedGuides(){
  var id=Guid.NewGuid();var text="Check the documented indicator.";var handler=new Reviews(true);
  var verifier=new ModelSupportVerifier(new HttpClient(handler){BaseAddress=new("http://localhost/")},"Ollama","fixture");
  var answer=new Answer("supported",[],[new AdviceStep(text,[new Citation(id,text)])],[],"Test",null);
  var result=await verifier.VerifyAsync("indicator",answer,[new(id,Guid.NewGuid(),"Indicator","1","test",text+" SOURCE_PREREQUISITE",null),new(Guid.NewGuid(),Guid.NewGuid(),"Other","1","test","UNRELATED_GUIDE",null)],default);
  Assert.True(result.Supported);var body=Assert.Single(handler.Bodies);Assert.Contains("SOURCE_PREREQUISITE",body);Assert.DoesNotContain("UNRELATED_GUIDE",body);
 }
 [Fact] public async Task QuoteSupportMustPassBeforeSurroundingContextIsReviewed(){
  var id=Guid.NewGuid();var passage=new Passage(id,Guid.NewGuid(),"USB","1","test","Quoted sentence. UNCITED_CONTEXT",null);
  var handler=new Reviews(false);var verifier=new ModelSupportVerifier(new HttpClient(handler){BaseAddress=new("http://localhost/")},"Ollama","fixture");
  var result=await verifier.VerifyAsync("question",Answer(id),[passage],default);Assert.False(result.Supported);Assert.Single(handler.Bodies);Assert.DoesNotContain("UNCITED_CONTEXT",handler.Bodies[0]);
 }
 [Fact] public async Task ValidQuotesStillRequireContextAndPrerequisiteReview(){
  var id=Guid.NewGuid();var passage=new Passage(id,Guid.NewGuid(),"USB","1","test","Quoted sentence. CONTEXT_PREREQUISITE",null);
  var handler=new Reviews(true,false);var verifier=new ModelSupportVerifier(new HttpClient(handler){BaseAddress=new("http://localhost/")},"Ollama","fixture");
  var result=await verifier.VerifyAsync("question",Answer(id),[passage],default);Assert.False(result.Supported);Assert.Equal(2,handler.Bodies.Count);Assert.DoesNotContain("CONTEXT_PREREQUISITE",handler.Bodies[0]);Assert.Contains("CONTEXT_PREREQUISITE",handler.Bodies[1]);
 }
 [Fact] public async Task BothReviewsMustSupportAllSteps(){var id=Guid.NewGuid();var handler=new Reviews(true,true);var verifier=new ModelSupportVerifier(new HttpClient(handler){BaseAddress=new("http://localhost/")},"Ollama","fixture");Assert.True((await verifier.VerifyAsync("question",Answer(id),[new(id,Guid.NewGuid(),"USB","1","test","Quoted sentence.",null)],default)).Supported);Assert.Equal(2,handler.Bodies.Count);}
 private static Answer Answer(Guid id)=>new("supported",[],[new AdviceStep("Check a setting.",[new Citation(id,"Quoted sentence.")])],[],"Live Ollama",null);
 private sealed class Reviews(params bool[] supported):HttpMessageHandler {public List<string> Bodies=[];protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){Bodies.Add(await request.Content!.ReadAsStringAsync(ct));var value=supported[Bodies.Count-1];var review=JsonSerializer.Serialize(new{coverage=value?"complete":"none",checks=new[]{new{step=0,supported=value}}});return new(HttpStatusCode.OK){Content=new StringContent(JsonSerializer.Serialize(new{done=true,done_reason="stop",message=new{content=review}}),Encoding.UTF8,"application/json")};}}
}
